const q=$input.first().json.query||{};const job=S(q.job).replace(/[^0-9A-Za-z-]/g,'');
let info={};if(job){try{info=await h.httpRequest({url:H+'cbs-sm8-job?no='+encodeURIComponent(job),json:true,timeout:15000})||{};}catch(x){info={};}}
const D={job:job,site:S(info.site),client:S(info.client)};
const CSS='*{box-sizing:border-box}body{margin:0;background:#f2f2f0;color:#161616;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;font-size:16px;line-height:1.4}'
+'header{background:#3d4043;color:#fff;padding:12px 16px;border-bottom:4px solid #F47920;position:sticky;top:0;z-index:5}header .nav{display:flex;flex-wrap:wrap;gap:6px 14px}header a.hub{color:#ffb37a;font-size:13px;text-decoration:none}header h1{margin:4px 0 0;font-size:20px}header p{margin:3px 0 0;color:#ccc;font-size:13px}'
+'.wrap{max-width:860px;margin:0 auto;padding:14px}.tools{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}'
+'.btn{background:#F47920;color:#fff;text-decoration:none;font-weight:600;border-radius:8px;padding:8px 14px;font-size:14px;border:0;font-family:inherit;cursor:pointer}.btn.ghost{background:#fff;color:#1d1d1d;border:1px solid #d9d9d6}.btn.sm{padding:6px 10px;font-size:13px}.btn:disabled{opacity:.5}.btn.red{background:#fff;color:#b3261e;border:1px solid #e9b6b1}'
+'.strip{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:12px}.pst{background:#fff;border:1px solid #d9d9d6;border-radius:10px;padding:8px 6px;text-align:center}.pst b{display:block;font-size:18px;line-height:1.2}.pst span{font-size:12px;color:#555}.pst.ed{cursor:pointer}.pst.ed:hover{border-color:#F47920}.pst.ok{border-color:#b9dfc1;background:#f1faf2}.pst.warn{border-color:#f2d398;background:#fff8ea}@media(max-width:560px){.strip{grid-template-columns:repeat(2,1fr)}}'
+'.flt{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}.flt button{border:1px solid #d9d9d6;background:#fff;border-radius:20px;padding:5px 11px;font:inherit;font-size:13px;cursor:pointer}.flt button.on{background:#F47920;color:#fff;border-color:#F47920}.srch{width:100%;font:inherit;padding:10px 12px;border:1px solid #ccc;border-radius:10px;margin-bottom:10px}'
+'.card{background:#fff;border:1px solid #d9d9d6;border-radius:12px;margin-bottom:10px;padding:12px 14px}.t{font-weight:600}.m{color:#555;font-size:14px;margin-top:2px}.ds{white-space:pre-wrap;font-size:14px;margin-top:6px;color:#333}.b{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px;align-items:center}.amt{float:right;font-weight:700}'
+'.tag{display:inline-block;font-size:12px;font-weight:600;border-radius:20px;padding:1px 8px;margin-left:6px;background:#eee;color:#333;vertical-align:middle}.tag.Raised{background:#eee}.tag.Priced{background:#e6efff;color:#1f5fbf}.tag.Submitted{background:#fff1d6;color:#8a5a00}.tag.Approved{background:#e3f4e6;color:#1d6b2c}.tag.Rejected{background:#fde3e1;color:#b3261e}'
