+'.opr{display:flex;align-items:center;gap:8px;padding:7px 0;border-top:1px solid #eee}.opr span{flex:1}';
const nav='<div class="nav"><a class="hub" href="/webhook/cbs-admin">&larr; Operations Hub</a>'+(job?'<a class="hub" href="/webhook/cbs-job-file?job='+encodeURIComponent(job)+'">Job File</a>':'')+'</div>';
const sub=e([D.site,D.client].filter(Boolean).join(' \u00b7 ')||'Chelmsford Building Services');
const html='<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Variations - Job '+e(job)+'</title><script src="/webhook/cbs-guard"></script><style>'+CSS+'</style><script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script></head><body><header>'+nav+'<h1>Variations'+(job?' \u00b7 Job '+e(job):'')+'</h1><p>'+sub+'</p></header><div class="wrap" id="app">'+(job?'<div class="empty">Loading\u2026</div>':'<div class="empty">Open variations from a job.</div>')+'</div><script>window.D='+JSON.stringify(D).replace(/</g,'\\u003c')+';</script>'+(job?'<script>('+client.toString()+')();</script>':'')+'</body></html>';
return [{json:{html:html}}];

function client(){
var D=window.D,JOB=D.job,app=document.getElementById('app'),DATA=null,FILTER='all',Q='',LOGO=null;
var STS=['Raised','Priced','Submitted','Approved','Rejected'];
function s(v){return v==null?'':String(v);}
function e(t){return s(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function n(v){var x=Number(v);return isNaN(x)?0:x;}
function gbp(v){var neg=n(v)<0;return (neg?'-':'')+'\u00a3'+Math.abs(n(v)).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function dmy(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:s(d);}
function today(){var d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
function who(){var x='';try{var m=JSON.parse(localStorage.getItem('cbs_me')||'null');if(m&&m.name)x=m.name;}catch(z){}if(!x){try{x=localStorage.getItem('cbs_name')||'';}catch(z){}}if(!x){x=(prompt('Your name:')||'').trim();if(x){try{localStorage.setItem('cbs_name',x);}catch(z){}}}return x;}
function post(body){var by=who();if(!by)return Promise.resolve({ok:false,message:'',cancel:true});body.job=JOB;body.by=by;
 return fetch('/webhook/cbs-variation-act',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){if(!r.ok)throw 0;return r.json();}).catch(function(){return {ok:false,message:'Could not save. Check your connection and try again.'};});}
function load(){return fetch('/webhook/cbs-variations-data?job='+encodeURIComponent(JOB),{cache:'no-store'}).then(function(r){return r.json();}).then(function(d){DATA=d;render();}).catch(function(){app.innerHTML='<div class="empty">Could not load the variations. Refresh to try again.</div>';});}
function dlg(html){var o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg">'+html+'</div>';document.body.appendChild(o);o.close=function(){o.remove();};return o;}
function guard(o,isDirty){o.addEventListener('click',function(ev){if(ev.target!==o)return;if(isDirty&&isDirty()&&!confirm('Close without saving your changes?'))return;o.close();});}
function rows(){return (DATA&&DATA.rows)||[];}
function vis(){var q=Q.toLowerCase();return rows().filter(function(r){if(FILTER!=='all'&&s(r.status)!==FILTER)return false;if(!q)return true;return [r.var_no,r.title,r.description,r.instructed_by,r.instruction_via].join(' ').toLowerCase().indexOf(q)>-1;});}
function render(){var T=DATA.totals||{},h='';
 h+='<div class="strip"><div class="pst ed" id="cv"><b>'+(T.contract==null?'Set':gbp(T.contract))+'</b><span>Contract value \u270e</span></div><div class="pst ok"><b>'+gbp(T.approved)+'</b><span>Approved variations</span></div><div class="pst"><b>'+(T.current==null?'\u2013':gbp(T.current))+'</b><span>Current value</span></div><div class="pst warn"><b>'+gbp(T.pending)+'</b><span>Awaiting decision</span></div></div>';
 if(T.days)h+='<p class="m" style="margin:-4px 0 10px">Approved variations add '+T.days+' day'+(T.days===1?'':'s')+' to the programme.</p>';
 h+='<div class="tools"><button class="btn" id="add">+ Add variation</button><button class="btn ghost" id="log">Variations log PDF</button><button class="btn ghost" id="opt">Instruction options</button></div>';
 var C={};rows().forEach(function(r){C[r.status]=(C[r.status]||0)+1;});
 h+='<div class="flt">'+['all'].concat(STS).map(function(k){var c=k==='all'?rows().length:(C[k]||0);return '<button data-f="'+k+'" class="'+(FILTER===k?'on':'')+'">'+(k==='all'?'All':k)+' ('+c+')</button>';}).join('')+'</div>';
 h+='<input class="srch" id="q" placeholder="Search variations" value="'+e(Q)+'">';
 var L=vis();
 if(!rows().length)h+='<div class="empty">No variations on this job yet. Tap + Add variation to log one.</div>';
 else if(!L.length)h+='<div class="empty">Nothing matches.</div>';
 L.forEach(function(r){var st=s(r.status)||'Raised',tk=s(r.prog_item_ids).split(',').filter(Boolean).length;
  h+='<div class="card" data-id="'+r.id+'"><div class="t">'+e(r.var_no)+' \u00b7 '+e(r.title)+'<span class="tag '+e(st)+'">'+e(st)+'</span>'+(s(r.cost)!==''?'<span class="amt">'+gbp(r.cost)+'</span>':'')+'</div>'
  +'<div class="m">'+[r.instructed_by?'Instructed by '+e(r.instructed_by):'',r.instructed_on?dmy(r.instructed_on):'',r.instruction_via?'via '+e(r.instruction_via):'',s(r.time_days)!==''&&n(r.time_days)?(n(r.time_days)>0?'+':'')+n(r.time_days)+' day'+(Math.abs(n(r.time_days))===1?'':'s'):''].filter(Boolean).join(' \u00b7 ')+'</div>'
  +(r.description?'<div class="ds">'+e(r.description)+'</div>':'')
  +((st==='Approved'||st==='Rejected')&&r.decided_by?'<div class="m">'+st+' by '+e(r.decided_by)+(r.decided_on?' on '+dmy(r.decided_on):'')+'</div>':'')
  +(tk?'<div class="m">'+tk+' programme task'+(tk===1?'':'s')+' added</div>':'')
  +'<div class="b"><select class="st" data-a="st">'+STS.map(function(x){return '<option'+(x===st?' selected':'')+'>'+x+'</option>';}).join('')+'</select><button class="btn ghost sm" data-a="edit">Edit</button>'
  +(st==='Approved'?'<button class="btn ghost sm" data-a="task">+ Programme task</button>':'')
  +'<button class="btn ghost sm" data-a="pdf">Variation sheet</button><button class="btn red sm" data-a="del">Delete</button></div>'
  +(r.history?'<details><summary class="m" style="cursor:pointer">History</summary><div class="hist">'+e(r.history)+'</div></details>':'')+'</div>';});
 app.innerHTML=h;
 document.getElementById('cv').onclick=contractDlg;document.getElementById('add').onclick=function(){editDlg(null);};document.getElementById('log').onclick=logDlg;document.getElementById('opt').onclick=optDlg;
 app.querySelectorAll('[data-f]').forEach(function(b){b.onclick=function(){FILTER=b.getAttribute('data-f');render();};});
 var qi=document.getElementById('q');qi.oninput=function(){Q=qi.value;var p=qi.selectionStart;render();var x=document.getElementById('q');x.focus();try{x.setSelectionRange(p,p);}catch(z){}};
 app.querySelectorAll('[data-a]').forEach(function(el){var id=el.closest('.card').getAttribute('data-id');var r=rows().filter(function(x){return String(x.id)===id;})[0];var a=el.getAttribute('data-a');
  if(a==='st'){el.onchange=function(){statusDlg(r,el.value);};return;}
  el.onclick=function(){if(a==='edit')editDlg(r);else if(a==='task')taskDlg(r);else if(a==='pdf')sheet(r);else if(a==='del')delVar(r);};});}
function contractDlg(){var T=DATA.totals||{};if(!T.hasJob){alert('This job has no Job File record yet. Set up the Job File first.');return;}
 var o=dlg('<h2>Contract value</h2><div class="m">The accepted quote value for this job. Approved variations are added to it to give the current value.</div><label class="f">Contract value (\u00a3)</label><input type="number" step="0.01" id="cvv" value="'+(T.contract==null?'':T.contract)+'"><div class="msg" id="cvm"></div><div class="b"><button class="btn" id="cvs">Save</button><button class="btn ghost" id="cvx">Cancel</button></div>');
 var start=o.querySelector('#cvv').value;guard(o,function(){return o.querySelector('#cvv').value!==start;});o.querySelector('#cvx').onclick=o.close;
 o.querySelector('#cvs').onclick=function(){var b=this;b.disabled=true;post({a:'contract',value:o.querySelector('#cvv').value}).then(function(r){if(r.ok){o.close();load();}else{b.disabled=false;if(!r.cancel)o.querySelector('#cvm').textContent=r.message||'Could not save.';}});};}
function optSel(cur){var O=(DATA.opts||[]).slice();if(cur&&O.indexOf(cur)<0)O.push(cur);return '<select id="fv"><option value="">Choose\u2026</option>'+O.map(function(x){return '<option'+(x===cur?' selected':'')+'>'+e(x)+'</option>';}).join('')+'</select>';}
function editDlg(r){r=r||{};
 var o=dlg('<h2>'+(r.id?'Edit '+e(r.var_no):'New variation')+'</h2><label class="f">Title</label><input type="text" id="ft" value="'+e(r.title)+'" placeholder="e.g. Extra socket outlets in kitchen">'
 +'<label class="f">Description</label><textarea id="fd" placeholder="What was asked for and what it involves">'+e(r.description)+'</textarea>'
 +'<div class="row2"><div><label class="f">Instructed by</label><input type="text" id="fb" value="'+e(r.instructed_by)+'" placeholder="Client, architect\u2026"></div><div><label class="f">Date instructed</label><input type="date" id="fo" value="'+e(r.instructed_on||(r.id?'':today()))+'"></div></div>'
 +'<label class="f">Instruction received via</label>'+optSel(s(r.instruction_via))
 +'<div class="row2"><div><label class="f">Cost (\u00a3)</label><input type="number" step="0.01" id="fc" value="'+e(r.cost)+'" placeholder="Leave blank until priced"></div><div><label class="f">Time impact (days)</label><input type="number" step="1" id="fdays" value="'+e(r.time_days)+'" placeholder="0"></div></div>'
 +'<div class="msg" id="fm"></div><div class="b"><button class="btn" id="fs">Save</button><button class="btn ghost" id="fx">Cancel</button></div>');
 var ids=['ft','fd','fb','fo','fv','fc','fdays'],st=ids.map(function(i){return o.querySelector('#'+i).value;}).join('|');
 function dirty(){return ids.map(function(i){return o.querySelector('#'+i).value;}).join('|')!==st;}
 guard(o,dirty);o.querySelector('#fx').onclick=function(){if(dirty()&&!confirm('Close without saving your changes?'))return;o.close();};
 o.querySelector('#fs').onclick=function(){var t=o.querySelector('#ft').value.trim();if(!t){alert('Give the variation a title.');return;}var b=this;b.disabled=true;
  post({a:'save',id:r.id||0,title:t,description:o.querySelector('#fd').value,instructed_by:o.querySelector('#fb').value,instructed_on:o.querySelector('#fo').value,instruction_via:o.querySelector('#fv').value,cost:o.querySelector('#fc').value,time_days:o.querySelector('#fdays').value})
  .then(function(x){if(x.ok){o.close();load();}else{b.disabled=false;if(!x.cancel)o.querySelector('#fm').textContent=x.message||'Could not save.';}});};}
function statusDlg(r,st){if(st===r.status)return;
 if(st!=='Approved'&&st!=='Rejected'){if(!confirm('Mark '+r.var_no+' as '+st+'?')){render();return;}post({a:'status',id:r.id,status:st}).then(function(x){if(!x.ok&&!x.cancel)alert(x.message||'Could not save.');load();});return;}
 var o=dlg('<h2>'+st+': '+e(r.var_no)+'</h2><div class="m">'+e(r.title)+(s(r.cost)!==''?' \u00b7 '+gbp(r.cost):'')+'</div><div class="row2"><div><label class="f">'+st+' by</label><input type="text" id="db" value="'+e(r.instructed_by)+'" placeholder="Who decided"></div><div><label class="f">Date</label><input type="date" id="dd" value="'+today()+'"></div></div><label class="f">Note (optional)</label><textarea id="dn" style="min-height:60px"></textarea><div class="msg" id="dm"></div><div class="b"><button class="btn" id="dg">Mark '+st.toLowerCase()+'</button><button class="btn ghost" id="dx">Cancel</button></div>');
 function cancel(){o.close();render();}o.addEventListener('click',function(ev){if(ev.target===o)cancel();});o.querySelector('#dx').onclick=cancel;
 o.querySelector('#dg').onclick=function(){var b=this;b.disabled=true;post({a:'status',id:r.id,status:st,decided_by:o.querySelector('#db').value,decided_on:o.querySelector('#dd').value,note:o.querySelector('#dn').value}).then(function(x){if(x.ok){o.close();load();}else{b.disabled=false;if(!x.cancel)o.querySelector('#dm').textContent=x.message||'Could not save.';}});};}
function taskDlg(r){var P=DATA.phases||[];if(!P.length){alert('This job has no open programme with phases yet. Create the programme first.');return;}
 var o=dlg('<h2>Add to programme</h2><div class="m">Adds a task for '+e(r.var_no)+' to the job programme.</div><label class="f">Phase</label><select id="tp">'+P.map(function(p){return '<option value="'+p.id+'" data-e="'+e(p.end)+'">'+e(p.name)+(p.start?' ('+dmy(p.start)+(p.end&&p.end!==p.start?' \u2013 '+dmy(p.end):'')+')':'')+'</option>';}).join('')+'</select><label class="f">Task name</label><input type="text" id="tn" value="'+e(r.var_no+' '+r.title)+'"><div class="row2"><div><label class="f">Start</label><input type="date" id="ts"></div><div><label class="f">End</label><input type="date" id="te"></div></div>'+(n(r.time_days)?'<div class="note">This variation adds '+n(r.time_days)+' day'+(Math.abs(n(r.time_days))===1?'':'s')+'.</div>':'')+'<div class="msg" id="tm"></div><div class="b"><button class="btn" id="tg">Add task</button><button class="btn ghost" id="tx">Cancel</button></div>');
 guard(o);o.querySelector('#tx').onclick=o.close;
 o.querySelector('#tg').onclick=function(){var b=this;b.disabled=true;post({a:'addtask',id:r.id,phase_id:o.querySelector('#tp').value,name:o.querySelector('#tn').value,start_on:o.querySelector('#ts').value,end_on:o.querySelector('#te').value}).then(function(x){if(x.ok){o.close();load();}else{b.disabled=false;if(!x.cancel)o.querySelector('#tm').textContent=x.message||'Could not add.';}});};}
function delVar(r){if(!confirm('Delete '+r.var_no+' ('+r.title+')?'))return;if(!confirm('Are you sure? This permanently removes the variation and its history.'+(s(r.prog_item_ids)?' Programme tasks it added stay on the programme.':'')))return;
 post({a:'delete',id:r.id}).then(function(x){if(!x.ok&&!x.cancel)alert(x.message||'Could not delete.');load();});}
function optDlg(){var o=dlg('<h2>Instruction options</h2><div class="m">The choices for \u201cInstruction received via\u201d.</div><div id="ol"></div><div class="row2" style="margin-top:10px"><input type="text" id="on" placeholder="Add an option"><button class="btn ghost" id="oa">Add</button></div><div class="msg" id="om"></div><div class="b"><button class="btn ghost" id="ox">Close</button></div>');
 function draw(){o.querySelector('#ol').innerHTML=(DATA.opts||[]).map(function(x){return '<div class="opr"><span>'+e(x)+'</span><button class="btn red sm" data-v="'+e(x)+'">Remove</button></div>';}).join('');
  o.querySelectorAll('[data-v]').forEach(function(b){b.onclick=function(){var v=b.getAttribute('data-v');if(!confirm('Are you sure you want to remove \u201c'+v+'\u201d? Variations already using it keep it.'))return;b.disabled=true;post({a:'opt',op:'del',value:v}).then(function(x){if(!x.ok&&!x.cancel)o.querySelector('#om').textContent=x.message||'Could not remove.';refresh();});};});}
 function refresh(){fetch('/webhook/cbs-variations-data?job='+encodeURIComponent(JOB),{cache:'no-store'}).then(function(r){return r.json();}).then(function(d){DATA=d;draw();render();});}
 draw();o.querySelector('#ox').onclick=o.close;guard(o);
 o.querySelector('#oa').onclick=function(){var v=o.querySelector('#on').value.trim();if(!v)return;var b=this;b.disabled=true;post({a:'opt',op:'add',value:v}).then(function(x){b.disabled=false;if(x.ok){o.querySelector('#on').value='';refresh();}else if(!x.cancel)o.querySelector('#om').textContent=x.message||'Could not add.';});};}
function getLogo(){if(LOGO!==null)return Promise.resolve(LOGO);return fetch('/webhook/cbs-programme-logo').then(function(r){return r.json();}).then(function(d){LOGO=(d&&d.lg)||'';return LOGO;}).catch(function(){LOGO='';return '';});}
function head(doc,lg,title,W){doc.setFillColor(244,121,32);doc.rect(0,0,W,3,'F');var lx=14;if(lg){try{var pr=doc.getImageProperties(lg),hh=13,ww=pr.width*hh/pr.height;if(ww>48){ww=48;hh=pr.height*ww/pr.width;}doc.addImage(lg,'PNG',14,7,ww,hh);lx=14+ww+5;}catch(z){}}
