/* Variations data for one job: the log, contract value, totals, instruction-via options and programme phases. */
const h=this.helpers,H='https://old-hub.example/webhook/';
const S=v=>v==null?'':String(v).trim();const jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();const num=v=>Number(v)||0;
const q=$input.first().json.query||{};const job=S(q.job).replace(/[^0-9A-Za-z-]/g,'');
const list=async t=>{try{const L=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t='+t,body:{},json:true,timeout:30000});return (Array.isArray(L)?L:[]).filter(r=>r&&r.id!=null);}catch(e){return [];}};
if(!job)return [{json:{ok:false,message:'No job number.'}}];
const [V,J,O]=await Promise.all([list('variations'),list('jobrows'),list('selectopts')]);
const rows=V.filter(r=>jk(r.job_no)===jk(job)).sort((x,y)=>num(S(x.var_no).replace(/\D/g,''))-num(S(y.var_no).replace(/\D/g,''))||num(x.id)-num(y.id));
const jr=J.filter(r=>jk(r.ref)===jk(job)).sort((x,y)=>num(y.id)-num(x.id))[0]||null;
let opts=O.filter(o=>S(o.reg)==='variations'&&S(o.field)==='instruction_via').map(o=>S(o.value)).filter(Boolean);
const DEF=['Site instruction','Email','Verbal','Architect\u2019s instruction','Drawing revision','Client request'];
const custom=opts.length>0;if(!custom)opts=DEF.slice();
let phases=[];try{const P=await h.httpRequest({url:H+'cbs-programme-data?job='+encodeURIComponent(job),json:true,timeout:20000});const st=S(P&&P.programme&&P.programme.status);if(st==='Open'||st==='Draft')phases=((P&&P.phases)||[]).map(p=>({id:p.id,name:S(p.name),start:S(p.start_eff),end:S(p.end_eff)}));}catch(e){}
const sum=st=>rows.filter(r=>S(r.status)===st).reduce((m,r)=>m+num(r.cost),0);
const cv=jr&&jr.contract_value!=null&&S(jr.contract_value)!==''?num(jr.contract_value):null;
const approved=sum('Approved');
const totals={contract:cv,approved:approved,current:cv==null?null:cv+approved,pending:sum('Priced')+sum('Submitted'),days:rows.filter(r=>S(r.status)==='Approved').reduce((m,r)=>m+num(r.time_days),0),hasJob:!!jr};
return [{json:{ok:true,job:job,site:S(jr&&jr.site),client:S(jr&&jr.client),rows:rows,totals:totals,opts:opts,optsCustom:custom,phases:phases}}];

