const V=(await list('variations')).filter(r=>jk(r.job_no)===jk(job));
const find=id=>V.find(r=>String(r.id)===S(id));
const hist=(r,line)=>[S(r&&r.history),stamp+' - '+line].filter(Boolean).join(String.fromCharCode(10));
if(a==='save'){
 const title=S(b.title).slice(0,160);if(!title)return R(false,{message:'Give the variation a title.'});
