 const row={title:title,description:S(b.description).slice(0,4000),instructed_by:S(b.instructed_by).slice(0,120),instructed_on:isD(b.instructed_on)?S(b.instructed_on):'',instruction_via:S(b.instruction_via).slice(0,80),cost:cost,time_days:td===''?'':String(Math.round(Number(td)))};
