 if(id){const r=find(id);if(!r)return R(false,{message:'That variation was not found. Refresh the page.'});
  const was=S(r.status)||'Raised';let line='Edited by '+by;
  if(S(r.cost)!==cost&&!(S(r.cost)===''&&cost==='')&&Number(S(r.cost))!==Number(cost))line+=' (cost '+(S(r.cost)===''?'not set':fmt(r.cost))+' to '+(cost===''?'not set':fmt(cost))+')';
  if(was==='Raised'&&cost!==''){row.status='Priced';line+=', now Priced';}
  else if(was==='Priced'&&cost===''){row.status='Raised';line+=', back to Raised';}
  row.history=hist(r,line);await save('variations',id,row,true);return R(true,{id:id});}
 const n=V.reduce((m,r)=>Math.max(m,num(S(r.var_no).replace(/\D/g,''))),0)+1;
 Object.assign(row,{job_no:job,var_no:'VAR-'+String(n).padStart(3,'0'),status:cost!==''?'Priced':'Raised',decided_by:'',decided_on:'',files_json:'[]',prog_item_ids:'',pdf_url:'',created_by:by,created_at:now,history:stamp+' - Raised by '+by+(cost!==''?' and priced at '+fmt(cost):'')});
 const res=await save('variations',0,row,false);return R(true,{id:num(res&&res.id),var_no:row.var_no});
}
const r=find(b.id);if(!r)return R(false,{message:'That variation was not found. Refresh the page.'});
